#[verus_spec]
pub fn try_write(&self) -> Option<RwLockWriteGuard<'_, T, G>> {
    proof_decl!{
        let tracked mut guard_perm: Option<PointsTo<T>> = None;
        let tracked mut guard_token: Option<OneRightKnowledge<HalfPerm<T>, NoPerm<T>, 3>> = None;
    }
    proof!{
        use_type_invariant(self);
        lemma_consts_properties();
    }

    let guard = G::guard();
    if atomic_with_ghost!(
        self.lock => compare_exchange(0, WRITER);
        update prev -> next;
        returning res;
        ghost g => {
            // When compare_exchange(0, WRITER) succeeds:
            // - prev = 0, next = WRITER, res = Ok(0)
            // - We're acquiring a write lock

            // First, we need to transition core_token from Left to Right
            // To do this, we need to:
            // 1. Join left_token back into core_token
            // 2. Join upreader_guard_token back into core_token
            // 3. Transition from Left to Right

            proof {
                use_type_invariant(self);

                // Join left_token back into core_token
                let tracked left_token_option = g.upreader_guard_token;
                if left_token_option is Some {
                    let tracked left_token = left_token_option;
                    g.core_token.validate_with_one_left_knowledge(left_token);
                    g.core_token.join_one_left_knowledge(left_token);
                }

                // Join upreader_guard_token back into core_token
                let tracked upreader_guard_token_option = g.upreader_guard_token;
                if upreader_guard_token_option is Some {
                    let tracked upreader_guard_token = upreader_guard_token_option;
                    g.core_token.validate_with_one_left_owner(upreader_guard_token);
                    g.core_token.join_one_left_owner(upreader_guard_token);
                }

                // Now core_token should have frac() == 3 and is_resource_owner()
                // We can now change to Right
                let tracked a: PointsTo<T> = g.core_token.take_resource_left();
                guard_perm = Option::Some(a);

                // Split OneRightKnowledge from core_token
                let tracked guard_tok = g.core_token.split_one_right_knowledge();
                guard_token = Option::Some(guard_tok);
            }
        }
    ).is_ok() {
        Some(
            RwLockWriteGuard {
                inner: self,
                guard,
                tracked_perm: Tracked(guard_perm.tracked_unwrap()),
                tracked_token: Tracked(guard_token.tracked_unwrap()),
            },
        )
    } else {
        None
    }
}

